// src/ui/components/text-field/controller.ts
function textFieldController(opts = {}) {
  let value = opts.value ?? "";
  const size = opts.size ?? "md";
  return {
    get value() {
      return value;
    },
    size,
    fill: opts.fill ?? size !== "sm",
    disabled: opts.disabled ?? false,
    commit(next) {
      if (next === value) return null;
      value = next;
      opts.onChange?.(next);
      return next;
    },
    sync(next) {
      value = next;
    }
  };
}

