  handleCursor(index, proj) {
    if (index >= 4) return ROTATE_CURSOR;
    if (!proj) return null;
    const c = this.center(proj);
    const k = this.corners(proj)[index];
    return c && k ? resizeCursor(k[0] - c[0], k[1] - c[1]) : null;
  }
