      ctx.save();
      ctx.font = `12px ${theme.fontFamily}`;
      ctx.fillStyle = T.pearsons.color;
      ctx.textAlign = "center";
      ctx.textBaseline = "top";
      ctx.fillText(T.pearsons.text, T.pearsons.x, T.pearsons.y);
