    wick.dataset.role = "wick";
    const transparency = fieldRow({
      label: "Transparency",
      control: buildFieldControl({ kind: "number", value: d.transparency ?? 50, min: 0, max: 100, step: 1, integer: true, fill: false, commit: "blur", onChange: (n) => {
        if (Number.isFinite(n)) actions.patch({ transparency: Math.max(0, Math.min(100, Math.round(n))) });
      } }).el
    });
