function tsiRatio(src, long, short) {
  const mom = change(src);
  const numer = ema(ema(mom, long), short);
  const denom = ema(ema(map(mom, Math.abs), long), short);
  return zip(numer, denom, (a, b) => b === 0 ? 0 : a / b);
}
