      maxIdx.push(i);
      while (minIdx.length > 0 && bars[minIdx[minIdx.length - 1]].low >= b.low) minIdx.pop();
      minIdx.push(i);
      while (bars[from].time < b.time - span) from += 1;
      while (maxIdx[0] < from) maxIdx.shift();
      while (minIdx[0] < from) minIdx.shift();
